import itertools

def get_monochromatic_count(triangles, coloring):
    count = 0
    for t in triangles:
        if coloring[t[0]] == coloring[t[1]] == coloring[t[2]]:
            count += 1
    return count

def is_design(subset, n):
    pairs = {}
    for t in subset:
        for i, j in itertools.combinations(t, 2):
            pairs[(i, j)] = pairs.get((i, j), 0) + 1
    return all(v == 2 for v in pairs.values()) and len(pairs) == n * (n-1) // 2

def find_any_design(n, k):
    triples = list(itertools.combinations(range(n), 3))
    for subset in itertools.combinations(triples, k * n * (n-1) // 6):
        if is_design(subset, n):
            return subset
    return None

