import itertools

def get_monochromatic_count(triangles, coloring):
    count = 0
    for t in triangles:
        if coloring[t[0]] == coloring[t[1]] == coloring[t[2]]:
            count += 1
    return count

def is_design_k(subset, n, k):
    pairs = {}
    for t in subset:
        for i, j in itertools.combinations(t, 2):
            pairs[(i, j)] = pairs.get((i, j), 0) + 1
    return all(v == k for v in pairs.values()) and len(pairs) == n * (n-1) // 2

# Let's find an STS(9) more efficiently.
def find_sts9_fast():
    # A known STS(9) is:
    # {0,1,2}, {3,4,5}, {6,7,8}, {0,3,6}, {1,4,7}, {2,5,8}, {0,4,8}, {1,5,6}, {2,3,7}
    # Let's check this.
    sts = [(0,1,2), (3,4,5), (6,7,8), (0,3,6), (1,4,7), (2,5,8), (0,4,8), (1,5,6), (2,3,7)]
    if is_design_k(sts, 9, 1):
        return sts
    return None

sts9 = find_sts9_fast()
print(f"STS(9) found: {sts9}")
if sts9:
    for coloring in itertools.product([0, 1], repeat=9):
        m = get_monochromatic_count(sts9, coloring)
        if m < 2:
            print(f"Found coloring with M={m} for n=9: {coloring}")
            break
    else:
        print("All colorings for n=9, k=1 have M >= 2")
else:
    print("No STS(9) found.")
